int main() {
    char P[105], A[105];
    if (scanf("%s", P) != 1) return 0;
    if (scanf("%s", A) != 1) return 0;

    int cnt[26] = {0};

    for (int i = 0; P[i] != '\0'; i++) {
        cnt[P[i] - 'a']++;
    }

    for (int i = 0; A[i] != '\0'; i++) {
        if (A[i] != '*') {
            int idx = A[i] - 'a';
            cnt[idx]--;
            if (cnt[idx] < 0) {
                printf("N\n");
                return 0;
            }
        }
    }

    printf("S\n");
    return 0;
}
